<div class="page-heading"><div><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>Business & account settings<span class="green">.</span></h1><p>Your full contact details stay private. Supplier name, city, description and business type are public.</p></div></div><div class="two-column"><form method="post" action="/profile/save" class="panel"><?= csrf() ?><h2>Business profile</h2><?php foreach(['name'=>'Business name','type'=>'Business type','contact'=>'Contact person (private)','phone'=>'Phone (private)','city'=>'City','address'=>'Business address (private)'] as $key=>$label):?><label><?= $label ?><input name="<?= $key ?>" value="<?= e($business[$key]) ?>" <?= in_array($key,['name','type','city'])?'required':'' ?> maxlength="<?= $key==='address'?1000:($key==='phone'?40:($key==='name'?150:100)) ?>"></label><?php endforeach;?><label>Public description<textarea name="description" rows="4" maxlength="2000"><?= e($business['description']) ?></textarea></label><button class="btn btn-primary">Save business profile</button></form><div><form method="post" action="/password/save" class="panel"><?= csrf() ?><h2>Account security</h2><p><?= e($user['email']) ?> <span class="badge soft-badge"><?= $user['verified_at']?'Verified':'Not verified' ?></span></p><label>Current password<input type="password" name="current_password" required autocomplete="current-password"></label><label>New password<input type="password" name="password" required minlength="12" maxlength="200" autocomplete="new-password"></label><button class="btn btn-outline-secondary">Update password</button></form><?php if(!$user['verified_at']):?><form action="/verify/resend" method="post" class="panel"><?= csrf() ?><h2>Verify your email</h2><p>Verification links expire after one hour.</p><button class="btn btn-primary">Resend verification email</button></form><?php endif;?>
<?php if($role==='retailer'):?><section class="panel"><h2>Saved addresses</h2><?php foreach($addresses as $a):?><div class="address-row"><div><strong><?= e($a['label']) ?></strong><p><?= e($a['address'].', '.$a['city']) ?></p></div><form method="post" action="/address/delete"><?= csrf() ?><input type="hidden" name="id" value="<?= $a['id'] ?>"><button class="icon-button" aria-label="Delete address">×</button></form></div><?php endforeach;?><?php if(!$addresses):?><p>No saved addresses. Add one below for delivery.</p><?php endif;?></section><form method="post" action="/address/save" class="panel"><?= csrf() ?><h2>Add a delivery address</h2><label>Label<input name="label" required maxlength="100" placeholder="Main store"></label><label>Full address<textarea name="address" required maxlength="1000" rows="2"></textarea></label><label>City<input name="city" required maxlength="100"></label><div class="form-row"><label>Latitude (optional)<input type="number" name="lat" min="-90" max="90" step="any"></label><label>Longitude (optional)<input type="number" name="lng" min="-180" max="180" step="any"></label></div><small>Coordinates enable straight-line distance estimates and radius eligibility. Route distance is a future mapping integration.</small><button class="btn btn-primary">Save address</button></form><?php endif;?></div></div>
<?php if($role==='wholesaler'):?><form method="post" action="/fulfillment/save" class="panel"><?= csrf() ?><h2>Fulfillment settings</h2><div class="form-row"><label class="check-label"><input type="checkbox" name="pickup" <?= $fulfillment['pickup']?'checked':'' ?>> Enable local pickup</label><label class="check-label"><input type="checkbox" name="delivery" <?= $fulfillment['delivery']?'checked':'' ?>> Enable delivery</label></div><div class="form-row"><label>Delivery fee (blank = quote required)<input name="delivery_fee" inputmode="decimal" value="<?= $fulfillment['delivery_fee']===null?'':number_format($fulfillment['delivery_fee']/100,2,'.','') ?>"></label><label>Delivery radius in km (optional)<input name="delivery_radius" type="number" min="0.1" step="any" value="<?= e($fulfillment['delivery_radius']) ?>"></label><label>Lead time<input name="lead_time" required value="<?= e($fulfillment['lead_time']) ?>" maxlength="100"></label></div><div class="form-row"><label>Supplier latitude<input name="lat" type="number" min="-90" max="90" step="any" value="<?= e($fulfillment['lat']) ?>"></label><label>Supplier longitude<input name="lng" type="number" min="-180" max="180" step="any" value="<?= e($fulfillment['lng']) ?>"></label></div><label>Pickup instructions (shared with purchasing retailers)<textarea name="pickup_instructions" maxlength="1000" rows="3"><?= e($fulfillment['pickup_instructions']) ?></textarea></label><button class="btn btn-primary">Save fulfillment settings</button></form><?php endif;?>
